      de: "Dieser einzige historische Zoo Nepals liegt in Jawalakhel und bietet Familien die Möglichkeit, bengalische Tiger, Panzernashörner und unzählige Vogelarten hautnah zu erleben.",
      hu: "Nepál egyetlen történelmi állatkertje Jawalakhelben található, ahol a családok testközelből figyelhetik meg a bengáli tigriseket, az indiai orrszarvúkat és számos madárfajt.",
      ro: "Această singură grădină zoologică istorică din Nepal se află în Jawalakhel, oferind familiilor șansa de a vedea de aproape tigri bengalezi, rinoceri indieni și nenumărate specii de păsări.",
      en: "This sole historic zoo of Nepal is located in Jawalakhel, offering families the chance to see Bengal tigers, Indian rhinoceroses, and countless bird species up close.",
      es: "Este único zoológico histórico de Nepal se encuentra en Jawalakhel y ofrece a las familias la oportunidad de ver de cerca tigres de Bengala, rinocerontes de un solo cuerno e innumerables especies de aves.",
      pt: "Este único jardim zoológico histórico do Nepal localiza-se em Jawalakhel e oferece às famílias a oportunidade de observar de perto tigres-de-bengala, rinocerontes-indianos e inúmeras espécies de aves.",
      fr: "L'unique zoo historique du Népal est situé à Jawalakhel et offre aux familles la possibilité d'observer de près des tigres du Bengale, des rhinocéros unicornes et d'innombrables espèces d'oiseaux.",
