      hu: ["2015-ben nyílt meg", "Területe kb. 2 hektár", "Évente kb. 500.000 látogató", "Hullámvasúttal és óriáskerékkel rendelkezik", "Indiai partnerrel fejlesztették ki", "Tripureshworban, Kathmanduban található"],
      ro: ["Deschis în 2015", "Suprafață de aproximativ 2 hectare", "Aproximativ 500.000 de vizitatori anual", "Dispune de un roller coaster și o roată mare", "Dezvoltat cu un partener indian", "Situat în Tripureshwor, Kathmandu"],
