      ro: ["Fondat în 2003", "Suprafață de aproximativ 5,5 hectare", "Protejează macaraua Sarus (Antigone antigone)", "Situat în districtul Rupandehi", "Parte a complexului Lumbini", "Administrat de National Trust for Nature Conservation"],
      en: ["Established in 2003", "Area approx. 5.5 hectares", "Protects Sarus Crane (Antigone antigone)", "Located in Rupandehi District", "Part of the Lumbini complex", "Managed by National Trust for Nature Conservation"],
