      es: ["Primera quesería de cabra nepalesa.", "Pionero en el cultivo de olivos en Nepal.", "Punto histórico clave para el comercio.", "Muy popular para estancias en casas de familias (homestays)."],
      pt: ["Primeira queijaria de cabra nepalesa.", "Pioneira no cultivo de azeitonas no Nepal.", "Ponto histórico importante para o comércio.", "Muito popular para estadias em casas de família (homestays)."],
