      ro: ["Chitlang se află la aproximativ 22 de kilometri sud-vest de Kathmandu.", "Satul găzduiește prima fabrică de brânză de capră din Nepal.", "Livezile de peri au fost plantate cu peste 100 de ani în urmă, sub Ranas.", "Localitatea este situată la o altitudine medie de 1.700 de metri.", "Este un punct important pe vechiul traseu de drumeție 'Thankot-Chitlang'.", "Satul deține inscripții din perioada Licchavi (secolele V-VIII)."],
      en: ["Chitlang is located approximately 22 kilometers southwest of Kathmandu.", "The village hosts the very first goat cheese factory in Nepal.", "The pear orchards were established over 100 years ago under the Ranas.", "The settlement is situated at an average altitude of 1,700 meters.", "It is a key point on the ancient 'Thankot-Chitlang' walking trail.", "The village contains stone inscriptions dating back to the Licchavi era."],
